#!/bin/bash
# Create the following Nextcloud Flow:
# When (File Created) and (File System Tag) (is tagged with) (FileDrop) -> Run Script Field
# Copy the one-liner script into script field in Nextcloud Flow settings
/bin/bash -c 'filename="%f"; size_in_bytes=$(stat -c "%s" "$filename"); size=$(awk "BEGIN { printf \"%.2f\", $size_in_bytes / (1024 * 1024) }"); current_time=$(TZ="America/Denver" date "+%I:%M %p"); MAIL_CONTENT_FILE=$(mktemp); echo -e "From: \"$FILEDROP_SENDER_NAME\" <$SMTP_NAME>\nTo: <$FILEDROP_EMAIL_RECIPIENT>\nSubject: New notification from $FILEDROP_SENDER_NAME\nContent-Type: text/html; charset=\"UTF-8\"\nMIME-Version: 1.0\n\n<!DOCTYPE html>\n<html>\n<body style=\"margin: 0; padding: 0; background-color: #f4f4f4; font-family: -apple-system, BlinkMacSystemFont, \047Segoe UI\047, Roboto, Helvetica, Arial, sans-serif;\">\n  <div style=\"width: 100%; max-width: 600px; margin: 20px auto; background-color: #ffffff; border-radius: 8px; border: 1px solid #e0e0e0; padding: 40px; box-sizing: border-box;\">\n    <h2 style=\"margin-top: 0; color: #005a9e;\">New File Notification</h2>\n    <p style=\"color: #333333;\">A file has been uploaded via your Nextcloud FileDrop:</p>\n    <div style=\"margin-top: 25px; line-height: 1.6;\">\n      <strong style=\"color: #555555;\">File Name:</strong> ${filename##*/}<br>\n      <strong style=\"color: #555555;\">Size:</strong> ${size} MB<br>\n      <strong style=\"color: #555555;\">Time:</strong> ${current_time} MDT\n    </div>\n    <hr style=\"border: 0; border-top: 1px solid #eeeeee; margin: 30px 0;\">\n    <p style=\"font-size: 12px; color: #999999; text-align: center;\">$FILEDROP_SENDER_NAME</p>\n  </div>\n</body>\n</html>" > "$MAIL_CONTENT_FILE"; curl --url "smtps://$SMTP_HOST:$SMTP_PORT" --user "$SMTP_NAME:$SMTP_PASSWORD" --mail-from "$SMTP_NAME" --mail-rcpt "$FILEDROP_EMAIL_RECIPIENT" --upload-file "$MAIL_CONTENT_FILE"; rm "$MAIL_CONTENT_FILE"'